# ! [doc = " This crate contains pre-baked ICU4X data, generated by `icu4x-datagen`. The tool"] # ! [doc = " fetches locale data from CLDR and transforms them into const code in statics that"] # ! [doc = " ICU4X can load, via databake. `lib.rs` in this crate is manually written, but all"] # ! [doc = " other code is generated."] # ! [doc = ""] # ! [doc = " This crate can be regenerated when there's a new CLDR version, though that is unlikely"] # ! [doc = " to result in changes in most cases (currently this only covers list formatting data, which"] # ! [doc = " is rather stable). It may need to be regenerated when updating ICU4X versions, especially"] # ! [doc = " across major versions, in case it fails to compile after an update."] # ! [doc = ""] # ! [doc = " It must be regenerated when adding new locales to Rust, or if Rust's usage of ICU4X"] # ! [doc = " grows to need more kinds of data."] # ! [doc = ""] # ! [doc = " To regenerate the data, run this command:"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = " icu4x-datagen -W --pretty --use-separate-crates \\"] # ! [doc = " --format baked --locales @en @es @fr @it @ja @pt @ru @tr @zh @zh-Hans @zh-Hant \\"] # ! [doc = " -m ListAndV1 -o src/data"] # ! [doc = " ```"] # ! [allow (elided_lifetimes_in_paths)] # ! [allow (internal_features)] # ! [allow (unreachable_pub)] # ! [doc (rust_logo)] # ! [feature (rustdoc_internals)] use split_decls_genesis :: ourprelude :: * ; pub struct BakedDataProvider ; include ! ("data/mod.rs") ; const _ : () = { impl_data_provider ! (BakedDataProvider) ; } ; pub const fn baked_data_provider () -> BakedDataProvider { BakedDataProvider } pub mod supported_locales { pub const EN : icu_locale :: Locale = icu_locale :: locale ! ("en") ; pub const ES : icu_locale :: Locale = icu_locale :: locale ! ("es") ; pub const FR : icu_locale :: Locale = icu_locale :: locale ! ("fr") ; pub const IT : icu_locale :: Locale = icu_locale :: locale ! ("it") ; pub const JA : icu_locale :: Locale = icu_locale :: locale ! ("ja") ; pub const PT : icu_locale :: Locale = icu_locale :: locale ! ("pt") ; pub const RU : icu_locale :: Locale = icu_locale :: locale ! ("ru") ; pub const TR : icu_locale :: Locale = icu_locale :: locale ! ("tr") ; pub const ZH_HANS : icu_locale :: Locale = icu_locale :: locale ! ("zh-Hans") ; pub const ZH_HANT : icu_locale :: Locale = icu_locale :: locale ! ("zh-Hant") ; }